class Solution {
  private int[] parent;

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  private boolean feasible(int n, int[][] edges, int k, int s) {
    for (int i = 0; i < n; i++) parent[i] = i;
    int comps = n;
    for (int[] e : edges) {
      if (e[3] != 1) continue;
      if (e[2] < s) return false;
      int a = find(e[0]), b = find(e[1]);
      if (a == b) return false;
      parent[a] = b;
      comps--;
    }
    for (int[] e : edges) {
      if (e[3] == 1 || e[2] < s) continue;
      int a = find(e[0]), b = find(e[1]);
      if (a != b) {
        parent[a] = b;
        comps--;
      }
    }
    int used = 0;
    for (int[] e : edges) {
      if (e[3] == 1 || e[2] >= s || 2L * e[2] < s) continue;
      int a = find(e[0]), b = find(e[1]);
      if (a != b) {
        parent[a] = b;
        comps--;
        used++;
      }
    }
    return comps == 1 && used <= k;
  }

  public int maxStability(int n, int[][] edges, int k) {
    parent = new int[n];
    int lo = 1, hi = 200_000;
    if (!feasible(n, edges, k, 1)) return -1;
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (feasible(n, edges, k, mid)) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }
}
